// UI Design Tokens —— 与 docs/design/ui-spec.md 对齐，单一来源
export const TOKENS = Object.freeze({
  grid: 16,
  scale: 2,
  base: { width: 1280, height: 720 },
  color: {
    bg: '#12141c',
    panel: '#1e2230',
    panelAlt: '#2a3042',
    border: '#3d4660',
    text: '#e8ecf5',
    textDim: '#9aa4bd',
    hp: '#e5484d',
    mp: '#3b82f6',
    gold: '#f5c542',
    interact: '#4ade80',
    danger: '#f97316',
    quality: { white: '#d6d9e0', green: '#4ade80', blue: '#3b82f6', purple: '#a855f7', orange: '#f97316' }
  },
  font: { xs: 12, sm: 14, md: 16, lg: 20, xl: 28 },
  space: { xs: 4, sm: 8, md: 12, lg: 16, xl: 24 },
  radius: { sm: 4, md: 8, lg: 12 },
  motion: { fast: 120, normal: 200, slow: 320, ease: 'cubic-bezier(0.2,0.8,0.2,1)' },
  z: { hud: 100, panel: 200, modal: 300, toast: 400 }
});

export function qualityColor(q) {
  return TOKENS.color.quality[q] || TOKENS.color.quality.white;
}

// 轻量事件总线适配层：优先复用基座 bus，缺失时降级为本地实现。
// 仅做转发，不持有游戏状态。
const local = new Map();

function localOn(evt, fn) {
  if (!local.has(evt)) local.set(evt, new Set());
  local.get(evt).add(fn);
  return () => local.get(evt) && local.get(evt).delete(fn);
}
function localEmit(evt, payload) {
  const set = local.get(evt);
  if (set) for (const fn of set) { try { fn(payload); } catch (e) { console.error('[ui-bus]', evt, e); } }
}

export function createBusAdapter(baseBus) {
  const hasBase = baseBus && typeof baseBus.on === 'function' && typeof baseBus.emit === 'function';
  return {
    on: (evt, fn) => (hasBase ? baseBus.on(evt, fn) : localOn(evt, fn)),
    emit: (evt, payload) => (hasBase ? baseBus.emit(evt, payload) : localEmit(evt, payload)),
    getSnapshot: () => (baseBus && typeof baseBus.getSnapshot === 'function' ? baseBus.getSnapshot() : {})
  };
}

// DOM 工具：安全创建元素、文本转义、整数像素对齐
import { TOKENS } from './ui-tokens.js';

export function el(tag, opts = {}, children = []) {
  const node = document.createElement(tag);
  if (opts.class) node.className = opts.class;
  if (opts.text != null) node.textContent = String(opts.text);
  if (opts.style) Object.assign(node.style, opts.style);
  if (opts.attrs) for (const [k, v] of Object.entries(opts.attrs)) node.setAttribute(k, String(v));
  for (const c of children) if (c) node.appendChild(c);
  return node;
}

export function px(n) {
  return `${Math.round(n / TOKENS.scale) * TOKENS.scale}px`;
}

export function clamp(v, lo, hi) {
  return Math.max(lo, Math.min(hi, Number.isFinite(v) ? v : lo));
}

export function safeNum(v, d = 0) {
  return Number.isFinite(v) ? v : d;
}

// HUD：血蓝、技能CD、金币、小地图、队友血条
import { TOKENS } from './ui-tokens.js';
import { el, clamp, safeNum } from './ui-dom.js';

export function createHud(root, bus) {
  const wrap = el('div', { class: 'ui-hud', attrs: { role: 'status', 'aria-live': 'polite' } });
  const hpBar = el('div', { class: 'bar bar-hp' }, [el('div', { class: 'bar-fill' })]);
  const mpBar = el('div', { class: 'bar bar-mp' }, [el('div', { class: 'bar-fill' })]);
  const gold = el('div', { class: 'hud-gold', text: '0' });
  const skills = el('div', { class: 'hud-skills' });
  const party = el('div', { class: 'hud-party' });
  const minimap = el('canvas', { class: 'hud-minimap', attrs: { width: 128, height: 96, 'aria-label': '小地图' } });
  wrap.append(hpBar, mpBar, gold, skills, party, minimap);
  root.appendChild(wrap);

  const ctx = minimap.getContext('2d');
  let last = {};

  function renderSkills(list) {
    skills.textContent = '';
    for (const s of Array.isArray(list) ? list : []) {
      const cd = clamp(safeNum(s.cd, 0), 0, 1);
      const cell = el('div', { class: 'skill', text: s.name || '?' });
      cell.style.setProperty('--cd', String(cd));
      skills.appendChild(cell);
    }
  }

  function renderParty(list) {
    party.textContent = '';
    for (const p of Array.isArray(list) ? list : []) {
      const row = el('div', { class: 'party-row' }, [
        el('span', { class: 'party-name', text: p.name || 'P' }),
        el('div', { class: 'bar bar-hp small' }, [el('div', { class: 'bar-fill' })])
      ]);
      const fill = row.querySelector('.bar-fill');
      fill.style.width = `${clamp(safeNum(p.hpRatio, 1), 0, 1) * 100}%`;
      party.appendChild(row);
    }
  }

  function renderMinimap(rooms) {
    ctx.clearRect(0, 0, minimap.width, minimap.height);
    ctx.fillStyle = TOKENS.color.bg;
    ctx.fillRect(0, 0, minimap.width, minimap.height);
    for (const r of Array.isArray(rooms) ? rooms : []) {
      if (!r.explored) continue;
      ctx.fillStyle = r.type === 'boss' ? TOKENS.color.danger : r.type === 'campfire' ? TOKENS.color.gold : TOKENS.color.panelAlt;
      ctx.fillRect(safeNum(r.x, 0), safeNum(r.y, 0), 10, 8);
    }
  }

  function update(snap) {
    last = snap || {};
    const hp = clamp(safeNum(last.hpRatio, 1), 0, 1);
    const mp = clamp(safeNum(last.mpRatio, 1), 0, 1);
    hpBar.firstChild.style.width = `${hp * 100}%`;
    mpBar.firstChild.style.width = `${mp * 100}%`;
    gold.textContent = String(safeNum(last.gold, 0));
    renderSkills(last.skills);
    renderParty(last.party);
    renderMinimap(last.rooms);
  }

  const off = bus.on('state:update', update);
  update(bus.getSnapshot());

  return { update, destroy() { off && off(); wrap.remove(); } };
}

// 背包：品质色、对比箭头、一键分解白绿
import { qualityColor, TOKENS } from './ui-tokens.js';
import { el, safeNum } from './ui-dom.js';

export function createInventory(root, bus) {
  const panel = el('div', { class: 'ui-panel ui-inventory hidden', attrs: { role: 'dialog', 'aria-label': '背包' } });
  const head = el('div', { class: 'panel-head' }, [
    el('span', { text: '背包' }),
    el('button', { class: 'btn', text: '一键分解白绿', attrs: { type: 'button' } })
  ]);
  const grid = el('div', { class: 'inv-grid' });
  panel.append(head, grid);
  root.appendChild(panel);

  head.querySelector('button').addEventListener('click', () => bus.emit('inventory:salvage', { qualities: ['white', 'green'] }));

  function render(items, equipped) {
    grid.textContent = '';
    for (const it of Array.isArray(items) ? items : []) {
      const cell = el('div', { class: 'inv-cell', attrs: { title: it.name || '' } });
      cell.style.borderColor = qualityColor(it.quality);
      cell.appendChild(el('span', { class: 'inv-name', text: it.name || '未知' }));
      const diff = safeNum(it.power, 0) - safeNum(equipped && equipped[it.slot] && equipped[it.slot].power, 0);
      if (diff !== 0) cell.appendChild(el('span', { class: diff > 0 ? 'arrow up' : 'arrow down', text: diff > 0 ? '▲' : '▼' }));
      cell.addEventListener('click', () => bus.emit('inventory:equip', { id: it.id }));
      grid.appendChild(cell);
    }
  }

  const off = bus.on('inventory:update', (p) => render(p && p.items, p && p.equipped));
  return {
    open() { panel.classList.remove('hidden'); },
    close() { panel.classList.add('hidden'); },
    render,
    destroy() { off && off(); panel.remove(); }
  };
}

// 地图面板：已探索房间、Boss 房、篝火图标
import { TOKENS } from './ui-tokens.js';
import { el, safeNum } from './ui-dom.js';

export function createMapPanel(root, bus) {
  const panel = el('div', { class: 'ui-panel ui-map hidden', attrs: { role: 'dialog', 'aria-label': '地图' } });
  const canvas = el('canvas', { attrs: { width: 480, height: 320 } });
  panel.appendChild(canvas);
  root.appendChild(panel);
  const ctx = canvas.getContext('2d');

  function render(rooms) {
    ctx.fillStyle = TOKENS.color.bg;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    for (const r of Array.isArray(rooms) ? rooms : []) {
      if (!r.explored) continue;
      ctx.fillStyle = r.type === 'boss' ? TOKENS.color.danger : r.type === 'campfire' ? TOKENS.color.gold : TOKENS.color.panelAlt;
      ctx.fillRect(safeNum(r.x, 0), safeNum(r.y, 0), 24, 18);
      ctx.strokeStyle = TOKENS.color.border;
      ctx.strokeRect(safeNum(r.x, 0), safeNum(r.y, 0), 24, 18);
    }
  }

  const off = bus.on('map:update', (p) => render(p && p.rooms));
  return { open() { panel.classList.remove('hidden'); }, close() { panel.classList.add('hidden'); }, render, destroy() { off && off(); panel.remove(); } };
}

// 商店面板：买药/钥匙/随机装备
import { qualityColor } from './ui-tokens.js';
import { el, safeNum } from './ui-dom.js';

export function createShop(root, bus) {
  const panel = el('div', { class: 'ui-panel ui-shop hidden', attrs: { role: 'dialog', 'aria-label': '商店' } });
  const list = el('div', { class: 'shop-list' });
  panel.appendChild(list);
  root.appendChild(panel);

  function render(goods, gold) {
    list.textContent = '';
    for (const g of Array.isArray(goods) ? goods : []) {
      const row = el('div', { class: 'shop-row' }, [
        el('span', { text: g.name || '商品' }),
        el('span', { class: 'price', text: `${safeNum(g.price, 0)}G` })
      ]);
      if (g.quality) row.style.borderLeftColor = qualityColor(g.quality);
      const btn = el('button', { class: 'btn', text: '购买', attrs: { type: 'button' } });
      btn.disabled = safeNum(gold, 0) < safeNum(g.price, 0);
      btn.addEventListener('click', () => bus.emit('shop:buy', { id: g.id }));
      row.appendChild(btn);
      list.appendChild(row);
    }
  }

  const off = bus.on('shop:update', (p) => render(p && p.goods, p && p.gold));
  return { open() { panel.classList.remove('hidden'); }, close() { panel.classList.add('hidden'); }, render, destroy() { off && off(); panel.remove(); } };
}

// 篝火面板：回血、存档、复活队友、快速回城
import { el } from './ui-dom.js';

export function createCampfire(root, bus) {
  const panel = el('div', { class: 'ui-panel ui-campfire hidden', attrs: { role: 'dialog', 'aria-label': '篝火' } });
  const actions = [
    ['回血', 'campfire:heal'],
    ['存档', 'campfire:save'],
    ['复活队友', 'campfire:revive'],
    ['快速回城', 'campfire:town']
  ];
  for (const [label, evt] of actions) {
    const btn = el('button', { class: 'btn', text: label, attrs: { type: 'button' } });
    btn.addEventListener('click', () => bus.emit(evt, {}));
    panel.appendChild(btn);
  }
  root.appendChild(panel);
  return { open() { panel.classList.remove('hidden'); }, close() { panel.classList.add('hidden'); }, destroy() { panel.remove(); } };
}

// 结算面板：本局掉落/金币/用时
import { qualityColor } from './ui-tokens.js';
import { el, safeNum } from './ui-dom.js';

export function createResults(root, bus) {
  const panel = el('div', { class: 'ui-panel ui-results hidden', attrs: { role: 'dialog', 'aria-label': '结算' } });
  const body = el('div', { class: 'results-body' });
  const back = el('button', { class: 'btn', text: '回城', attrs: { type: 'button' } });
  back.addEventListener('click', () => bus.emit('results:town', {}));
  panel.append(body, back);
  root.appendChild(panel);

  function render(data) {
    body.textContent = '';
    body.appendChild(el('div', { text: `金币 +${safeNum(data && data.gold, 0)}` }));
    body.appendChild(el('div', { text: `用时 ${safeNum(data && data.seconds, 0)}s` }));
    for (const it of (data && Array.isArray(data.drops)) ? data.drops : []) {
      const row = el('div', { class: 'drop-row', text: it.name || '装备' });
      row.style.color = qualityColor(it.quality);
      body.appendChild(row);
    }
  }

  const off = bus.on('results:show', render);
  return { open() { panel.classList.remove('hidden'); }, close() { panel.classList.add('hidden'); }, render, destroy() { off && off(); panel.remove(); } };
}

// 多人面板：本地同屏加入提示 + 局域网房间码（P1 占位）
import { el } from './ui-dom.js';

export function createMultiplayer(root, bus) {
  const panel = el('div', { class: 'ui-panel ui-multi hidden', attrs: { role: 'dialog', 'aria-label': '多人' } });
  const hint = el('div', { class: 'multi-hint', text: '本地同屏：按手柄 A 加入' });
  const codeInput = el('input', { class: 'input', attrs: { placeholder: '房间码（P1）', maxlength: 8 } });
  const joinBtn = el('button', { class: 'btn', text: '加入', attrs: { type: 'button' } });
  joinBtn.addEventListener('click', () => bus.emit('multi:join', { code: codeInput.value.trim() }));
  panel.append(hint, codeInput, joinBtn);
  root.appendChild(panel);
  return { open() { panel.classList.remove('hidden'); }, close() { panel.classList.add('hidden'); }, destroy() { panel.remove(); } };
}

// 设置：关闭震屏 / 减少粒子（低配降级）
import { el } from './ui-dom.js';

export function createSettings(root, bus) {
  const panel = el('div', { class: 'ui-panel ui-settings hidden', attrs: { role: 'dialog', 'aria-label': '设置' } });
  const opts = [
    ['关闭震屏', 'settings:shake'],
    ['减少粒子', 'settings:particles']
  ];
  for (const [label, evt] of opts) {
    const input = el('input', { attrs: { type: 'checkbox' } });
    input.addEventListener('change', () => bus.emit(evt, { enabled: input.checked }));
    panel.appendChild(el('label', { class: 'setting-row' }, [input, el('span', { text: label })]));
  }
  root.appendChild(panel);
  return { open() { panel.classList.remove('hidden'); }, close() { panel.classList.add('hidden'); }, destroy() { panel.remove(); } };
}

// 10 分钟新手引导步骤条：移动→打怪→捡装→回城→存档
import { el } from './ui-dom.js';

const STEPS = ['移动', '打怪', '捡装', '回城', '存档'];

export function createTutorial(root, bus) {
  const bar = el('div', { class: 'ui-tutorial hidden', attrs: { role: 'status', 'aria-live': 'polite' } });
  root.appendChild(bar);
  let idx = 0;

  function render() {
    bar.textContent = '';
    STEPS.forEach((s, i) => {
      bar.appendChild(el('span', { class: i === idx ? 'step active' : i < idx ? 'step done' : 'step', text: s }));
    });
  }

  const off = bus.on('tutorial:advance', () => { idx = Math.min(idx + 1, STEPS.length - 1); render(); });
  render();
  return { show() { bar.classList.remove('hidden'); }, hide() { bar.classList.add('hidden'); }, destroy() { off && off(); bar.remove(); } };
}

// UI 入口：init(rootEl, baseBus) 挂载全部增量 UI，返回销毁句柄
import { createBusAdapter } from './ui-bus.js';
import { createHud } from './hud.js';
import { createInventory } from './inventory.js';
import { createMapPanel } from './map-panel.js';
import { createShop } from './shop.js';
import { createCampfire } from './campfire.js';
import { createResults } from './results.js';
import { createMultiplayer } from './multiplayer.js';
import { createSettings } from './settings.js';
import { createTutorial } from './tutorial.js';

export function init(rootEl, baseBus) {
  if (!rootEl) throw new Error('[ui] rootEl required');
  const bus = createBusAdapter(baseBus);
  const parts = [
    createHud(rootEl, bus),
    createInventory(rootEl, bus),
    createMapPanel(rootEl, bus),
    createShop(rootEl, bus),
    createCampfire(rootEl, bus),
    createResults(rootEl, bus),
    createMultiplayer(rootEl, bus),
    createSettings(rootEl, bus),
    createTutorial(rootEl, bus)
  ];
  return {
    bus,
    destroy() { for (const p of parts) { try { p.destroy(); } catch (e) { console.error('[ui] destroy', e); } } }
  };
}

/* 迷宫冒险家 UI 样式 —— 基于 ui-spec Design Token，16px 网格 / 2x 整数缩放 */
:root {
  --bg: #12141c; --panel: #1e2230; --panel-alt: #2a3042; --border: #3d4660;
  --text: #e8ecf5; --text-dim: #9aa4bd; --hp: #e5484d; --mp: #3b82f6;
  --gold: #f5c542; --interact: #4ade80; --danger: #f97316;
  --q-white: #d6d9e0; --q-green: #4ade80; --q-blue: #3b82f6; --q-purple: #a855f7; --q-orange: #f97316;
  --radius: 8px; --ease: cubic-bezier(0.2,0.8,0.2,1);
}
* { box-sizing: border-box; }
.ui-hud, .ui-panel, .ui-tutorial { font-family: 'Segoe UI', system-ui, sans-serif; color: var(--text); }
.hidden { display: none !important; }

.ui-hud { position: absolute; inset: 0; pointer-events: none; z-index: 100; }
.bar { width: 200px; height: 16px; background: #0008; border: 2px solid var(--border); border-radius: var(--radius); overflow: hidden; margin: 8px; }
.bar.small { width: 120px; height: 10px; }
.bar-fill { height: 100%; width: 100%; transition: width 120ms var(--ease); }
.bar-hp .bar-fill { background: var(--hp); }
.bar-mp .bar-fill { background: var(--mp); }
.hud-gold { position: absolute; top: 8px; right: 16px; color: var(--gold); font-weight: 700; }
.hud-skills { position: absolute; bottom: 16px; left: 16px; display: flex; gap: 8px; }
.skill { width: 48px; height: 48px; background: var(--panel); border: 2px solid var(--border); border-radius: var(--radius); display: grid; place-items: center; font-size: 12px; position: relative; }
.skill::after { content: ''; position: absolute; inset: 0; background: #0009; transform: scaleY(var(--cd, 0)); transform-origin: bottom; }
.hud-party { position: absolute; top: 8px; left: 16px; display: flex; flex-direction: column; gap: 4px; }
.party-row { display: flex; align-items: center; gap: 8px; font-size: 12px; }
.hud-minimap { position: absolute; top: 8px; right: 16px; margin-top: 24px; border: 2px solid var(--border); border-radius: var(--radius); background: var(--bg); }

.ui-panel { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); background: var(--panel); border: 2px solid var(--border); border-radius: 12px; padding: 16px; min-width: 320px; z-index: 200; box-shadow: 0 8px 32px #000a; }
.panel-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; font-weight: 700; }
.btn { background: var(--panel-alt); color: var(--text); border: 2px solid var(--border); border-radius: var(--radius); padding: 6px 12px; cursor: pointer; transition: background 120ms var(--ease); }
.btn:hover:not(:disabled) { background: var(--interact); color: #000; }
.btn:disabled { opacity: 0.4; cursor: not-allowed; }
.input { background: var(--bg); color: var(--text); border: 2px solid var(--border); border-radius: var(--radius); padding: 6px 10px; margin: 8px 0; }

.inv-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 8px; }
.inv-cell { border: 2px solid var(--q-white); border-radius: var(--radius); padding: 6px; font-size: 12px; cursor: pointer; display: flex; flex-direction: column; gap: 2px; }
.arrow.up { color: var(--interact); } .arrow.down { color: var(--danger); }
.shop-row { display: flex; align-items: center; gap: 12px; padding: 6px; border-left: 4px solid var(--border); margin-bottom: 6px; }
.price { color: var(--gold); margin-left: auto; }
.drop-row { padding: 2px 0; }
.setting-row { display: flex; align-items: center; gap: 8px; padding: 6px 0; }
.multi-hint { color: var(--text-dim); margin-bottom: 8px; }

.ui-tutorial { position: absolute; bottom: 80px; left: 50%; transform: translateX(-50%); display: flex; gap: 8px; z-index: 100; }
.step { padding: 4px 10px; border-radius: var(--radius); background: var(--panel); border: 2px solid var(--border); font-size: 12px; color: var(--text-dim); }
.step.active { border-color: var(--interact); color: var(--text); }
.step.done { opacity: 0.5; }

@media (prefers-reduced-motion: reduce) { * { transition: none !important; } }
